import{_ as a,o,c as t,ag as n}from"./chunks/framework.Drp2S_UI.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md","lastUpdated":1792752159000}'),r={name:"en/guide/faq.md"};function i(s,e,d,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="where-is-the-complete-toolbar" tabindex="-1">Where is the complete toolbar? <a class="header-anchor" href="#where-is-the-complete-toolbar" aria-label="Permalink to &quot;Where is the complete toolbar?&quot;">​</a></h2><p>The library provides the editor and APIs; the repository demo assembles menus and toolbars. Run <code>npm run dev</code> and inspect <code>src/main.ts</code>, then select the controls your application needs. Use public commands instead of internal Draw methods.</p><h2 id="why-are-glyphs-missing-after-ready" tabindex="-1">Why are glyphs missing after ready? <a class="header-anchor" href="#why-are-glyphs-missing-after-ready" aria-label="Permalink to &quot;Why are glyphs missing after ready?&quot;">​</a></h2><p>Ready waits for runtime initialization, explicit fonts and first layout, not background downloads. Inspect page warnings, <code>getFontCoverageReport()</code> and <code>fontCoverageChange</code> for script, style and download status. Bunny basic fonts are not a complete Unicode collection. Unsupported or failed cases still need explicit files; see <a href="./font-and-esm-migration.html">font guidance</a>.</p><h2 id="why-does-an-installed-system-font-not-work" tabindex="-1">Why does an installed system font not work? <a class="header-anchor" href="#why-does-an-installed-system-font-not-work" aria-label="Permalink to &quot;Why does an installed system font not work?&quot;">​</a></h2><p>HarfBuzz requires accessible font bytes. Family names, CSS and OS installation do not register those bytes. Use initial <code>fonts</code> or <code>register.fonts()</code>, check individual results and then coverage. Bold, italic and regional forms need suitable actual faces.</p><h2 id="why-does-offline-mode-still-make-requests" tabindex="-1">Why does offline mode still make requests? <a class="header-anchor" href="#why-does-offline-mode-still-make-requests" aria-label="Permalink to &quot;Why does offline mode still make requests?&quot;">​</a></h2><p><code>autoDownloadFonts: false</code> disables automatic Bunny requests and automatic registration from that cache. It does not prohibit explicit font URLs, images or other application resources. Host required files with the app and inspect explicit URLs. Turning the switch off does not remove registered fonts.</p><h2 id="how-should-initialization-failure-or-rapid-unmount-work" tabindex="-1">How should initialization failure or rapid unmount work? <a class="header-anchor" href="#how-should-initialization-failure-or-rapid-unmount-work" aria-label="Permalink to &quot;How should initialization failure or rapid unmount work?&quot;">​</a></h2><p>Use <code>await Editor.create(...)</code> inside try/catch; failed instances are cleaned up. With synchronous construction, catch ready rejection and destroy the instance yourself. If unmount occurs before create resolves, use a cancellation flag and destroy the late result immediately. Your application owns external listeners, toolbars and resources.</p><h2 id="why-did-pagination-change-after-migration" tabindex="-1">Why did pagination change after migration? <a class="header-anchor" href="#why-did-pagination-change-after-migration" aria-label="Permalink to &quot;Why did pagination change after migration?&quot;">​</a></h2><p>Actual font faces and HarfBuzz shaping now determine widths rather than browser fallback or synthetic styles. Revalidate using fixed fonts, weights, widths and options. Background font registration can also change pagination.</p><h2 id="is-incremental-mode-always-faster" tabindex="-1">Is incremental mode always faster? <a class="header-anchor" href="#is-incremental-mode-always-faster" aria-label="Permalink to &quot;Is incremental mode always faster?&quot;">​</a></h2><p>No. It defaults to off. Dirty paragraphs are fully shaped and document flow, pagination and positions still run. Long paragraphs and cloning may be slower. See <a href="./lab.html">experimental options</a> and <a href="./../../guide/native-release-acceptance.html">acceptance measurements</a>.</p><h2 id="can-i-switch-to-svg-or-vector-pdf" tabindex="-1">Can I switch to SVG or vector PDF? <a class="header-anchor" href="#can-i-switch-to-svg-or-vector-pdf" aria-label="Permalink to &quot;Can I switch to SVG or vector PDF?&quot;">​</a></h2><p>Only Canvas pages are available. Standalone SVG export is deferred. <code>renderer</code>, removed <code>renderMode</code> and <code>textEngine</code> are not usable switches. SVG images/formulas do not constitute an SVG page engine; printing uses Canvas images.</p><h2 id="how-do-i-diagnose-production-404s" tabindex="-1">How do I diagnose production 404s? <a class="header-anchor" href="#how-do-i-diagnose-production-404s" aria-label="Permalink to &quot;How do I diagnose production 404s?&quot;">​</a></h2><p>Serve the full output over HTTP(S). Check chunk, worker, WASM and font paths, CORS and CSP. Do not copy just the entry JS or open with <code>file://</code>. The docs site&#39;s <code>DOCS_BASE</code> must match its Pages path; see <a href="./docs-deployment.html">deployment</a>.</p><h2 id="where-should-i-report-issues" tabindex="-1">Where should I report issues? <a class="header-anchor" href="#where-should-i-report-issues" aria-label="Permalink to &quot;Where should I report issues?&quot;">​</a></h2><p>Use <a href="https://github.com/HerbertHe/canvas-editor/issues" target="_blank" rel="noreferrer">HerbertHe/canvas-editor issues</a> with browser, fonts, configuration, a minimal document and reproduction steps. Coverage reports can contain document characters/locations; review them before sharing. Verify upstream plugins individually, and do not assume upstream maintainers support this fork.</p><p>Current input optimizations use the separate <code>lab.performanceProfile</code>; see <a href="./lab.html">configuration</a> and <a href="./benchmark.html">measured benchmark</a>.</p>',22)])])}const f=a(r,[["render",i]]);export{p as __pageData,f as default};
